-- Minimal isolated baseline for testing the chat-enhancements migration's
-- dynamic RPC update and its new tables/functions. Never run against production.
do $roles$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end
$roles$;

create schema if not exists auth;
create schema if not exists storage;
create table auth.users (id uuid primary key);
create or replace function auth.uid() returns uuid language sql stable as $$ select null::uuid $$;

create table storage.buckets (
  id text primary key,
  name text not null,
  public boolean not null default false,
  file_size_limit bigint,
  allowed_mime_types text[]
);
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('worth-it-chat-audio','worth-it-chat-audio',false,10485760,array['audio/webm'])
on conflict (id) do nothing;

create table public.worth_it_profiles (
  user_id uuid primary key references auth.users(id),
  worth_it_id bigint unique,
  username text,
  display_name text,
  avatar_url text
);
create table public.worth_it_friends (user_low_id uuid not null, user_high_id uuid not null);
create table public.worth_it_chat_conversations (
  id uuid primary key,
  conversation_type text not null,
  title text,
  created_by uuid references auth.users(id),
  invite_token text,
  created_at timestamptz not null default now()
);
create table public.worth_it_chat_members (
  conversation_id uuid not null references public.worth_it_chat_conversations(id),
  user_id uuid not null references auth.users(id),
  joined_at timestamptz not null default now(),
  last_read_at timestamptz,
  primary key (conversation_id,user_id)
);
create table public.worth_it_chat_messages (
  id bigint generated by default as identity primary key,
  conversation_id uuid not null references public.worth_it_chat_conversations(id),
  sender_user_id uuid not null references auth.users(id),
  body text not null default '',
  media_url text,
  media_type text,
  filtered_reason text,
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by_user_id uuid,
  constraint worth_it_chat_messages_media_type_check check (media_type is null or media_type in ('image','gif','video')),
  constraint worth_it_chat_message_body_len check (char_length(body) <= 500)
);
create table public.worth_it_chat_message_hides (message_id bigint not null, user_id uuid not null);
create table public.worth_it_chat_history_clears (user_id uuid not null, conversation_id uuid not null, cleared_at timestamptz);

-- The migration must preserve this existing RPC, adding only audio to its media
-- allow-list and private-storage marker validation.
create or replace function public.send_worth_it_chat_message(
    p_body text default '',
    p_conversation_id uuid default null,
    p_media_url text default null,
    p_media_type text default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
    actor_id uuid := auth.uid();
    target_id uuid := coalesce(p_conversation_id, '00000000-0000-4000-8000-000000000001'::uuid);
    media_kind text := nullif(p_media_type,'');
begin
    if media_kind not in ('image','gif','video') then
        return jsonb_build_object('success',false,'code','INVALID_MEDIA_TYPE');
    end if;
    if p_media_url is not null and (
        p_media_url !~ '^https://[^[:space:]]+$'
        or p_media_url !~ '^https://[^/]+/storage/v1/object/public/worth-it-chat-media/'
    ) then return jsonb_build_object('success',false,'code','INVALID_MEDIA_URL'); end if;
    return jsonb_build_object('success',true);
end; $$;
